\label{def:IPhO2026Problems_problem_IPhO_2026_3_B_1:HeatCapacityConstM}
\lean{IPhO2026.Problem3.B1.heatCapacityConstM}
\uses{def:IPhO2026Problems_problem_IPhO_2026_3_B_1:TorusParams}
